export const nextGeneration = (livingCells: Cell[]): Cell[] =>
  livingCells.filter(
    ([x, y]) =>
      livingCells.filter(
        ([otherX, otherY]) =>
          Math.abs(otherX - x) <= 1 &&
          Math.abs(otherY - y) <= 1 &&
          !(otherX === x && otherY === y),
      ).length === 2,
  );
